func fetchAsync(ctx context.Context, id string) <-chan Result {
    ch := make(chan Result, 1)              // buffered: no goroutine leak if unread
    go func() { defer close(ch); ch <- fetch(ctx, id) }()
    return ch                                // returns immediately
}
